<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentitySubjectVO;

trait UserFederatedIdentitySubjectAttributeHolder
{
    protected UserFederatedIdentitySubjectVO|string|null $subject = null;
    protected bool $subjectAssigned = false;

    public function getSubjectOrCurrent(UserFederatedIdentitySubjectVO $subject): UserFederatedIdentitySubjectVO
    {
        if ($this->subjectAssigned) {
            \assert(null !== $this->subject);
            return UserFederatedIdentitySubjectVO::from($this->subject);
        } else {
            return $subject;
        }
    }
    public function subjectTryBuildInitial(ConstraintFailList $error): ?UserFederatedIdentitySubjectVO
    {
        return  UserFederatedIdentitySubjectVO::tryFrom($this->subjectAssigned ? $this->subject : null, $error);
    }
    public function subject(UserFederatedIdentitySubjectVO|string $subject): static
    {
        $this->subject = $subject;
        $this->subjectAssigned = true;
        return $this;
    }
    public function getSubject(): ?string
    {
        return $this->subject instanceof UserFederatedIdentitySubjectVO ? $this->subject->value() : $this->subject;
    }
    public function isSubjectAssigned(): bool
    {
        return $this->subjectAssigned;
    }
    public function writeSubjectTo(mixed $att): void
    {
        if ($this->subjectAssigned) {
            \assert(null !== $this->subject);
            $att->subject($this->subject);
        }
    }
    public function readSubjectFrom(mixed $att): void
    {
        if ($att->isSubjectAssigned()) {
            $subject = $att->getSubject();
            \assert(null !== $subject);
            $this->subject($subject);
        }
    }
    public function unsetSubject(): static
    {
        $this->subjectAssigned = false;
        return $this;
    }
    protected function withDefaultSubject(): void
    {
    }
    protected function withAssertedSubjectRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->subjectAssigned = $this->subjectAssigned) {
            $value->subject = UserFederatedIdentitySubjectVO::tryFrom($this->subject, $errorsList);
        }
    }
}
